--
-- Структура таблицы `cust_categories`
--

CREATE TABLE `cust_categories` (
  `id` int NOT NULL,
  `tenant_id` int NOT NULL DEFAULT '1',
  `store_id` int NOT NULL DEFAULT '1',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Название фильтра',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'fa-filter' COMMENT 'Иконка FontAwesome',
  `color` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Цвет (orange, blue, green...)',
  `conditions` json NOT NULL COMMENT 'JSON с условиями фильтрации',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT 'Порядок сортировки',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Дамп данных таблицы `cust_categories`
--

INSERT INTO `cust_categories` (`id`, `tenant_id`, `store_id`, `title`, `icon`, `color`, `conditions`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Делали покупку', 'fa-filter', NULL, '{\"logic\": \"AND\", \"rules\": [{\"field\": \"total_orders\", \"value\": 1, \"operator\": \">=\"}]}', 1, 1, '2026-02-09 08:20:54', '2026-02-09 08:20:54');

