--
-- Структура таблицы `cust_customers`
--

CREATE TABLE `cust_customers` (
  `id` int NOT NULL,
  `tenant_id` int DEFAULT '1',
  `store_id` int NOT NULL DEFAULT '1',
  `status_id` int DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `birthday` date DEFAULT NULL,
  `addresses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `telegram_user_id` bigint DEFAULT NULL,
  `registration_date` date DEFAULT NULL,
  `total_orders` int NOT NULL DEFAULT '0',
  `total_spent` decimal(10,2) NOT NULL DEFAULT '0.00',
  `last_order_date` datetime DEFAULT NULL,
  `photo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `max_user_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'MAX user id linked by phone',
  `phone_verify_code` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '4-digit phone verification code',
  `phone_verify_expires_at` datetime DEFAULT NULL COMMENT 'verification code expiration',
  `phone_verified_at` datetime DEFAULT NULL COMMENT 'phone verified timestamp'
) ;

