--
-- Структура таблицы `mkt_discounts`
--

CREATE TABLE `mkt_discounts` (
  `id` int UNSIGNED NOT NULL,
  `tenant_id` int NOT NULL DEFAULT '1',
  `store_id` int NOT NULL DEFAULT '1',
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Название скидки/акции',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Описание для администратора',
  `discount_type` enum('percent','fixed','special_price') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'percent',
  `discount_value` decimal(12,2) NOT NULL COMMENT 'Значение скидки',
  `apply_to` enum('order','product','category','combo') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'order',
  `min_order_amount` decimal(12,2) DEFAULT NULL COMMENT 'Мин. сумма заказа',
  `max_discount_amount` decimal(12,2) DEFAULT NULL COMMENT 'Макс. размер скидки',
  `starts_at` datetime DEFAULT NULL COMMENT 'Начало действия',
  `ends_at` datetime DEFAULT NULL COMMENT 'Окончание действия',
  `schedule_days` json DEFAULT NULL COMMENT '[0,1,2,3,4,5,6] дни недели',
  `schedule_time_start` time DEFAULT NULL COMMENT 'Время начала в течение дня',
  `schedule_time_end` time DEFAULT NULL COMMENT 'Время окончания в течение дня',
  `usage_limit` int UNSIGNED DEFAULT NULL COMMENT 'Общий лимит использований',
  `usage_per_customer` int UNSIGNED DEFAULT NULL COMMENT 'Лимит на клиента',
  `usage_count` int UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Текущее кол-во использований',
  `priority` int NOT NULL DEFAULT '0' COMMENT 'Приоритет (выше = важнее)',
  `is_stackable` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Можно совмещать',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `mkt_discounts`
--

INSERT INTO `mkt_discounts` (`id`, `tenant_id`, `store_id`, `title`, `description`, `discount_type`, `discount_value`, `apply_to`, `min_order_amount`, `max_discount_amount`, `starts_at`, `ends_at`, `schedule_days`, `schedule_time_start`, `schedule_time_end`, `usage_limit`, `usage_per_customer`, `usage_count`, `priority`, `is_stackable`, `is_active`, `created_at`, `updated_at`) VALUES
