--
-- Структура таблицы `prod_stock_document_items`
--

CREATE TABLE `prod_stock_document_items` (
  `id` bigint UNSIGNED NOT NULL,
  `tenant_id` bigint UNSIGNED NOT NULL,
  `document_id` bigint UNSIGNED NOT NULL,
  `product_id` bigint UNSIGNED NOT NULL,
  `qty` decimal(12,3) NOT NULL COMMENT 'Количество',
  `unit_id` bigint UNSIGNED DEFAULT NULL COMMENT 'Единица измерения',
  `cost_price` decimal(14,6) DEFAULT NULL COMMENT 'Себестоимость за единицу',
  `price` decimal(14,6) DEFAULT NULL COMMENT 'Цена продажи за единицу',
  `purchase_price` decimal(14,6) DEFAULT NULL COMMENT 'Фактическая закупочная цена за единицу',
  `purchase_total` decimal(14,6) DEFAULT NULL COMMENT 'Фактически потрачено по позиции',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Позиции документа складского движения';

