--
-- Структура таблицы `ten_tenants`
--

CREATE TABLE `ten_tenants` (
  `id` int NOT NULL,
  `store_id` int NOT NULL DEFAULT '1',
  `name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'Мой Магазин',
  `slug` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subdomain` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `logo_light_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `logo_dark_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `favicon_light_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `favicon_dark_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `apple_touch_icon_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `android_icon_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price_rounding_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'none',
  `price_rounding_precision` tinyint NOT NULL DEFAULT '2',
  `timezone` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `site_name` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `site_description` text COLLATE utf8mb4_general_ci,
  `custom_domain` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sound_new_order_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sound_order_cancelled_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sound_new_message_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_stock_deduct_mode` enum('on_create','on_status') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'on_create' COMMENT 'When to deduct stock: on order creation or on selected status',
  `order_stock_deduct_status_id` int UNSIGNED DEFAULT NULL COMMENT 'Order status id that triggers stock deduction when mode=on_status',
  `img_webp_quality` tinyint UNSIGNED NOT NULL DEFAULT '82' COMMENT 'WebP quality for product photos (1-100)',
  `img_thumb_quality` tinyint UNSIGNED NOT NULL DEFAULT '72' COMMENT 'WebP quality for thumbnail (1-100)',
  `img_thumb_width` smallint UNSIGNED NOT NULL DEFAULT '480' COMMENT 'Thumbnail max width in px',
  `img_main_width` smallint UNSIGNED NOT NULL DEFAULT '1200' COMMENT 'Main product photo max width in px',
  `img_webp_aggressive` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Aggressive recompression for product WebP uploads',
  `img_delete_original` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Delete original file after WebP conversion',
  `telegram_bot_username` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Telegram bot username (without @)',
  `telegram_bot_token` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Telegram bot token from BotFather',
  `max_bot_token` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'MAX bot token for tenant authorization',
  `chat_welcome_message` text COLLATE utf8mb4_general_ci COMMENT 'Welcome text shown in customer chat',
  `chat_assistant_name` varchar(160) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Virtual assistant display name',
  `chat_operator_name` varchar(160) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Operator display name',
  `chat_quick_questions_json` text COLLATE utf8mb4_general_ci COMMENT 'JSON array of chat quick questions',
  `max_bot_id` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'MAX bot username or id for deep links',
  `max_login_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Enable customer login via MAX',
  `chat_widget_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Show customer chat button in storefront',
  `max_mini_app_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Enable MAX mini app link in bot auth message',
  `tg_mini_app_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Enable Telegram mini app link in bot auth message',
